def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find a full-width or full-height separator.
    sep = None
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != bg:
            sep = ("h", r, grid[r][0])
            break
    if sep is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if len(set(vals)) == 1 and vals[0] != bg:
                sep = ("v", c, vals[0])
                break
    if sep is None:
        return out

    axis, pos, sep_color = sep
    # Locate the non-background, non-separator object.
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != sep_color]
    if not cells:
        return out

    # Move the object toward the separator, keeping its shape intact.
    if axis == "h":
        if max(r for r, c in cells) < pos:
            dr = pos - 1 - max(r for r, c in cells)
            stripe_r = min(r for r, c in cells) + dr - 1
        else:
            dr = pos + 1 - min(r for r, c in cells)
            stripe_r = max(r for r, c in cells) + dr + 1
        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            out[r + dr][c] = grid[r][c]
        if 0 <= stripe_r < h:
            out[stripe_r] = [8] * w
    else:
        if max(c for r, c in cells) < pos:
            dc = pos - 1 - max(c for r, c in cells)
            stripe_c = min(c for r, c in cells) + dc - 1
        else:
            dc = pos + 1 - min(c for r, c in cells)
            stripe_c = max(c for r, c in cells) + dc + 1
        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            out[r][c + dc] = grid[r][c]
        if 0 <= stripe_c < w:
            for r in range(h):
                out[r][stripe_c] = 8
    return out
